// Structured logging + manual span timing (Node.js)
import { randomUUID } from 'crypto';

// Structured logger — always include traceId for correlation
function log(level, event, fields = {}) {
  const entry = {
    timestamp: new Date().toISOString(),
    level,
    event,
    ...fields,
  };
  process.stdout.write(JSON.stringify(entry) + '\n');
}

// Simple manual span — real code uses OpenTelemetry SDK
async function withSpan(spanName, traceId, fn) {
  const start = Date.now();
  log('DEBUG', 'span.start', { spanName, traceId });
  try {
    const result = await fn();
    log('INFO', 'span.end', { spanName, traceId, durationMs: Date.now() - start, ok: true });
    return result;
  } catch (err) {
    log('ERROR', 'span.error', { spanName, traceId, durationMs: Date.now() - start, error: err.message });
    throw err;
  }
}

// Usage in an HTTP handler
async function createOrderHandler(req, res) {
  const traceId = req.headers['x-trace-id'] ?? randomUUID();
  res.setHeader('x-trace-id', traceId); // echo back for client debugging

  try {
    const order = await withSpan('createOrder', traceId, () =>
      orderService.create(req.body)
    );
    log('INFO', 'order.created', { traceId, orderId: order.id, userId: req.user.id });
    res.status(201).json(order);
  } catch (err) {
    log('ERROR', 'order.failed', { traceId, error: err.message });
    res.status(500).json({ error: 'Order creation failed' });
  }
}
